// Liest die einzelne Formularübermittlung dieses Workflow-Laufs.
const raw = $input.first().json;
// Pflichtfelder werden getrimmt und gegen ihre maximale Länge geprüft.
const read = (name, max) => {
  const value = raw[name];
  if (typeof value !== 'string') throw new Error(`Feld ${name} fehlt`);
  const result = value.trim();
  if (!result || result.length > max) throw new Error(`Feld ${name} ist ungültig`);
  return result;
};
// Die intern erzeugte UUID schützt den Datenbank-Insert vor doppelter Verarbeitung.
const submissionKey = read('submission_key', 36);
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(submissionKey)) throw new Error('Ungültiger Formularschlüssel');
// Übersetzt die sichtbare Formularauswahl in stabile interne Servicewerte.
const services = { Mixing: 'mixing', Mastering: 'mastering', 'Mixing + Mastering': 'mixing_and_mastering' };
const choice = read('selected_service', 40);
if (!Object.prototype.hasOwnProperty.call(services, choice)) throw new Error('Ungültiger Service');
// Die E-Mail-Adresse wird nur formal geprüft; ein echter Besitznachweis folgt per Bestätigungslink.
const email = read('email', 254);
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Ungültige E-Mail-Adresse');
// Der Downloadlink wird nur syntaktisch geprüft und niemals geöffnet oder heruntergeladen.
const downloadUrl = read('download_url', 2000);
const link = /^https?:\/\/([a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)(?::([0-9]{1,5}))?(?:[/?#][^\s]*)?$/i.exec(downloadUrl);
const hostname = link?.[1];
const port = link?.[2];
const labels = hostname?.split('.') || [];
if (labels.length < 2 || labels.some((label) => !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label)) || (port && (Number(port) < 1 || Number(port) > 65535))) throw new Error('Ungültiger Downloadlink');
// Gibt ausschließlich normalisierte Werte an den parametrisierten PostgreSQL-Insert weiter.
return [{ json: { submission_key: submissionKey, first_name: read('first_name', 120), last_name: read('last_name', 120), email, selected_service: services[choice], message: read('message', 5000), download_url: downloadUrl } }];

parameters.query:
INSERT INTO public.inquiries (
  submission_key, first_name, last_name, email,
  selected_service, message, download_url
) VALUES (
  $1::uuid, $2, $3, $4, $5, $6, $7
)
ON CONFLICT (submission_key) DO NOTHING
RETURNING id::text AS inquiry_id, status;

