// Liest den Token ausschließlich aus dem Query-Parameter des Bestätigungs-Webhooks.
const token = $input.first().json?.query?.token;
// Nur ein 64-stelliger Hexwert wird weitergegeben; alles andere erhält den sicheren Wert `invalid`.
const verification_token = typeof token === 'string' && /^[0-9a-f]{64}$/i.test(token)
  ? token.toLowerCase()
  : 'invalid';
// Der nächste Crypto-Node hasht auch den ungültigen Ersatzwert in einem einheitlichen Ablauf.
return [{ json: { verification_token } }];

// Übersetzt das Datenbankergebnis in eine kontrollierte HTTP-Antwort für den Browser.
const outcome = $input.first().json.outcome;
// Jeder bekannte Ausgang besitzt einen festen Statuscode und einen festen, datenfreien Text.
const responses = {
  verified: [200, 'Vielen Dank. Ihre E-Mail-Adresse wurde bestätigt und die Demo-Anfrage wird jetzt geprüft.'],
  already_used: [200, 'Dieser Link wurde bereits verwendet. Die E-Mail-Adresse ist schon bestätigt.'],
  expired: [410, 'Dieser Bestätigungslink ist abgelaufen.'],
  revoked: [410, 'Dieser Bestätigungslink ist nicht mehr gültig.'],
  invalid: [400, 'Dieser Bestätigungslink ist ungültig.'],
  unavailable: [409, 'Die Anfrage kann mit diesem Link derzeit nicht bestätigt werden.'],
};
// Unbekannte Ergebnisse fallen auf eine neutrale, sichere Antwort zurück.
const [response_code, response_text] = responses[outcome] || responses.unavailable;
return [{ json: { outcome, response_code, response_text } }];

// Startet die Auswertung nur unmittelbar nach einer erstmalig erfolgreichen Bestätigung.
const item = $input.first().json;
// Wiederverwendete, abgelaufene oder ungültige Links erzeugen keinen weiteren Verarbeitungslauf.
if (item.outcome !== 'verified' || typeof item.inquiry_id !== 'string') return [];
return [{ json: { inquiry_id: item.inquiry_id } }];

// Prüft und pseudonymisiert eine einzelne bestätigte Anfrage vollständig lokal vor OpenAI.
const input = $input.first().json;
const allowedServices = new Set(['mixing', 'mastering', 'mixing_and_mastering']);
const inquiryId = typeof input.inquiry_id === 'string' ? input.inquiry_id : '';
const selectedService = typeof input.selected_service === 'string' ? input.selected_service : '';
const message = typeof input.message === 'string' ? input.message.trim() : '';
const firstName = typeof input.first_name === 'string' ? input.first_name.trim() : '';
const lastName = typeof input.last_name === 'string' ? input.last_name.trim() : '';
const knownEmail = typeof input.email === 'string' ? input.email.trim() : '';

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(inquiryId)) throw new Error('Ungültige inquiry_id');
if (!allowedServices.has(selectedService)) throw new Error('Ungültiger Service');
if (!message || message.length > 5000) throw new Error('Ungültiger Nachrichtentext');

// Sammelt gefundene sensible Textbereiche zunächst mit Position und Kategorie.
const candidates = [];
const addCandidate = (type, value, start, reinsertAllowed) => {
  if (typeof value !== 'string' || !value || !Number.isInteger(start) || start < 0) return;
  candidates.push({ type, value, start, end: start + value.length, reinsert_allowed: reinsertAllowed });
};
// Wiederverwendbare Hilfsfunktion für eindeutig erkennbare Kontaktmuster.
const addRegexMatches = (regex, type, reinsertAllowed, valueSelector = (match) => match[0], offsetSelector = () => 0) => {
  for (const match of message.matchAll(regex)) {
    const value = valueSelector(match);
    if (!value) continue;
    addCandidate(type, value, match.index + offsetSelector(match), reinsertAllowed);
  }
};
// Verhindert Teiltreffer, etwa den Namen `Demo` innerhalb von `Demo-Songs`.
const isWordCharacter = (character) => character ? /[\p{L}\p{N}_'-]/u.test(character) : false;
const addKnownValue = (value, type, reinsertAllowed) => {
  if (!value) return;
  const haystack = message.toLocaleLowerCase('de-DE');
  const needle = value.toLocaleLowerCase('de-DE');
  let fromIndex = 0;
  while (fromIndex <= haystack.length - needle.length) {
    const index = haystack.indexOf(needle, fromIndex);
    if (index < 0) break;
    const before = index > 0 ? message[index - 1] : '';
    const after = index + value.length < message.length ? message[index + value.length] : '';
    if (!isWordCharacter(before) && !isWordCharacter(after)) addCandidate(type, message.slice(index, index + value.length), index, reinsertAllowed);
    fromIndex = index + Math.max(value.length, 1);
  }
};

// Erkennt Kontaktwerte im Freitext, ohne Links aufzurufen oder Inhalte abzurufen.
addRegexMatches(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/giu, 'EMAIL', false);
for (const match of message.matchAll(/(?:https?:\/\/|www\.)[^\s<>"']+/giu)) {
  const value = match[0].replace(/[),.;!?]+$/u, '');
  addCandidate('URL', value, match.index, false);
}
addRegexMatches(/\+?\d[\d\s().\/-]{6,}\d/gu, 'PHONE', false);
addRegexMatches(/(?:^|[\s(])(@[A-Za-z0-9_][A-Za-z0-9_.-]{1,})/g, 'HANDLE', false, (match) => match[1], (match) => match[0].length - match[1].length);
// Sucht die bereits bekannten Formularnamen ohne Beachtung der Groß- und Kleinschreibung.
addKnownValue([firstName, lastName].filter(Boolean).join(' '), 'NAME', true);
addKnownValue(firstName, 'NAME', true);
addKnownValue(lastName, 'NAME', true);
addKnownValue(knownEmail, 'EMAIL', false);

// Längere Treffer gewinnen bei Überlappungen, damit zuerst der vollständige Name ersetzt wird.
candidates.sort((left, right) => (right.value.length - left.value.length) || (left.start - right.start));
const accepted = [];
for (const candidate of candidates) {
  const overlaps = accepted.some((item) => candidate.start < item.end && item.start < candidate.end);
  if (!overlaps) accepted.push(candidate);
}
accepted.sort((left, right) => left.start - right.start);

// Erstellt pro Kategorie eindeutige Platzhalter und hält die Zuordnung nur im lokalen Lauf.
const counters = {};
const mapByValue = new Map();
const piiMap = [];
for (const candidate of accepted) {
  const key = candidate.type + '\u0000' + candidate.value.toLocaleLowerCase('de-DE');
  let entry = mapByValue.get(key);
  if (!entry) {
    counters[candidate.type] = (counters[candidate.type] || 0) + 1;
    entry = {
      placeholder: '[[PII_' + candidate.type + '_' + counters[candidate.type] + ']]',
      type: candidate.type.toLowerCase(),
      original_value: candidate.value,
      reinsert_allowed: candidate.reinsert_allowed,
    };
    mapByValue.set(key, entry);
    piiMap.push(entry);
  }
  candidate.placeholder = entry.placeholder;
}

// Ersetzt von hinten nach vorne, damit gespeicherte Zeichenpositionen stabil bleiben.
let sanitizedMessage = message;
for (const candidate of [...accepted].sort((left, right) => right.start - left.start)) {
  sanitizedMessage = sanitizedMessage.slice(0, candidate.start) + candidate.placeholder + sanitizedMessage.slice(candidate.end);
}

// Eine zweite Prüfung stellt sicher, dass kein klar erkennbarer Kontaktwert übrig blieb.
const privacyReasons = [];
if (/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/iu.test(sanitizedMessage)) privacyReasons.push('unredacted_email_address');
if (/(?:https?:\/\/|www\.)\S+/iu.test(sanitizedMessage)) privacyReasons.push('unredacted_url');
if (/(?:^|\s)\+?\d[\d\s().\/-]{6,}\d(?=\s|[.,;:!?]|$)/u.test(sanitizedMessage)) privacyReasons.push('unredacted_phone_number');
if (/(?:^|\s)@[a-z0-9_][a-z0-9_.-]{1,}/iu.test(sanitizedMessage)) privacyReasons.push('unredacted_contact_handle');
if (/\b(?:mein name ist|ich heiße|ich heisse|my name is)\b(?!\s*\[\[PII_NAME_\d+\]\])/iu.test(sanitizedMessage)) privacyReasons.push('unresolved_self_identification');

// Leitet aus eindeutigen Servicebegriffen den in der Nachricht beschriebenen Umfang ab.
// Fehlt jeder Servicebegriff, bleibt die verpflichtende Formularauswahl ohne Konflikt maßgeblich.
const text = sanitizedMessage.toLocaleLowerCase('de-DE').replace(/\s+/g, ' ');
const mentionsMixing = /\bmixing\b/.test(text);
const mentionsMastering = /\bmastering\b/.test(text);
const onlyMixing = /\b(?:nur|ausschließlich|ausschliesslich|lediglich)\s+(?:das\s+)?mixing\b/.test(text);
const onlyMastering = /\b(?:nur|ausschließlich|ausschliesslich|lediglich)\s+(?:das\s+)?mastering\b/.test(text);
const noMixing = /\b(?:kein|keine|keinen)\s+(?:das\s+)?mixing\b/.test(text) || /\bnicht\s+(?:das\s+)?mixing\b/.test(text);
const noMastering = /\b(?:kein|keine|keinen)\s+(?:das\s+)?mastering\b/.test(text) || /\bnicht\s+(?:das\s+)?mastering\b/.test(text);
const ambiguousPhrase = /\b(?:unsicher|weiß nicht|weiss nicht|entweder mixing oder mastering|welchen service|welcher service|was ich brauche)\b/.test(text);
const contradictorySignals =
  (onlyMixing && onlyMastering) ||
  (noMixing && noMastering) ||
  (onlyMixing && noMixing) ||
  (onlyMastering && noMastering);

let messageService = null;
if (!contradictorySignals) {
  if (onlyMixing || (noMastering && !noMixing)) {
    messageService = 'mixing';
  } else if (onlyMastering || (noMixing && !noMastering)) {
    messageService = 'mastering';
  } else if (mentionsMixing && mentionsMastering) {
    messageService = 'mixing_and_mastering';
  } else if (mentionsMixing) {
    messageService = 'mixing';
  } else if (mentionsMastering) {
    messageService = 'mastering';
  }
}

// Die feste Matrix hat Vorrang: ein erkannter Umfang muss exakt zur Formularauswahl passen.
let ruleClassification = 'clear';
let ruleReason = messageService === null ? 'no_service_mentioned' : 'exact_service_match';
if (ambiguousPhrase || contradictorySignals) {
  ruleClassification = 'service_ambiguous';
  ruleReason = contradictorySignals ? 'contradictory_service_signals' : 'explicit_service_ambiguity';
} else if (messageService !== null && messageService !== selectedService) {
  ruleClassification = 'service_conflict';
  ruleReason = 'exact_service_mismatch';
}

// Gibt interne Prüfdaten und Zuordnung nur an lokale Folge-Nodes weiter.
return [{ json: {
  inquiry_id: inquiryId,
  selected_service: selectedService,
  sanitized_message: sanitizedMessage,
  pii_map: piiMap,
  pii_types: [...new Set(piiMap.map((entry) => entry.type))],
  redaction_status: privacyReasons.length ? 'unresolved' : 'complete',
  privacy_status: privacyReasons.length ? 'manual_review' : 'safe',
  privacy_reasons: privacyReasons,
  rule_classification: ruleClassification,
  rule_reason: ruleReason,
  rule_message_service: messageService,
} }];

// Lässt ausschließlich vollständig bereinigte Nachrichten in den OpenAI-Zweig.
const item = $input.first().json;
// Jeder unsichere Fall endet in der getrennten manuellen Prüfung.
if (item.privacy_status !== 'safe') return [];
return [{ json: item }];

// Baut die minimale OpenAI-Payload aus genau einer lokal freigegebenen Anfrage.
const item = $input.first().json;
// Nur die drei internen Servicewerte dürfen die Datenschutzgrenze passieren.
const allowedServices = new Set(['mixing', 'mastering', 'mixing_and_mastering']);
// Schutzprüfung: Unvollständige Pseudonymisierung stoppt vor dem externen API-Aufruf.
if (item.privacy_status !== 'safe' || item.redaction_status !== 'complete') throw new Error('Nachricht ist nicht für OpenAI freigegeben');
if (!allowedServices.has(item.selected_service)) throw new Error('Ungültiger Service für OpenAI');
if (typeof item.sanitized_message !== 'string' || !item.sanitized_message || item.sanitized_message.length > 5000) throw new Error('Ungültige pseudonymisierte Nachricht für OpenAI');
// Namen, E-Mail, Downloadlink, interne ID und Platzhalterzuordnung werden bewusst entfernt.
return [{ json: { selected_service: item.selected_service, message: item.sanitized_message } }];

// Leitet ausschließlich lokal markierte Datenschutzfälle in die manuelle Prüfung.
const item = $input.first().json;
// Der Zweig erhält nur die interne ID und keine sensiblen Freitextwerte.
if (item.privacy_status !== 'manual_review') return [];
return [{ json: { inquiry_id: item.inquiry_id } }];

// Behandelt die OpenAI-Ausgabe grundsätzlich als ungeprüfte externe Eingabe.
const input = $input.first().json;
// Holt die lokale Referenz mit Regeln und erlaubten Platzhaltern; diese Daten waren nie Teil der OpenAI-Payload.
const source = $('Datenschutz und Serviceregeln prüfen').first().json;
const allowedServices = new Set(['mixing', 'mastering', 'mixing_and_mastering']);
const allowedClassifications = new Set(['clear', 'service_conflict', 'service_ambiguous']);
// Diese lokalen Felder bleiben auch bei einer abgelehnten KI-Ausgabe erhalten.
const base = {
  inquiry_id: source.inquiry_id,
  selected_service: source.selected_service,
  rule_classification: source.rule_classification,
  rule_message_service: source.rule_message_service ?? null,
};
// Fehler führen immer zu einem datenarmen, eindeutig markierten Ergebnis ohne KI-Text.
const invalid = (validation_error) => [{ json: {
  ...base,
  validation_status: 'invalid',
  validation_error,
  classification: null,
  suggested_service: null,
  summary: null,
  clarification_question: null,
} }];

// Prüft zuerst die lokale Referenz und die abgeschlossene Pseudonymisierung.
try {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(base.inquiry_id)) return invalid('invalid_inquiry_id');
  if (!allowedServices.has(base.selected_service)) return invalid('invalid_selected_service');
  if (!allowedClassifications.has(base.rule_classification)) return invalid('invalid_local_rule');
  if (source.redaction_status !== 'complete' || source.privacy_status !== 'safe') return invalid('redaction_not_complete');

  // Baut die erlaubte Platzhaltermenge ausschließlich aus der lokalen Zuordnung.
  const piiMap = Array.isArray(source.pii_map) ? source.pii_map : [];
  const placeholderPattern = /^\[\[PII_[A-Z]+_\d+\]\]$/;
  const allowedPlaceholders = new Set();
  for (const entry of piiMap) {
    if (!entry || typeof entry.placeholder !== 'string' || !placeholderPattern.test(entry.placeholder)) return invalid('invalid_pii_map');
    if (allowedPlaceholders.has(entry.placeholder)) return invalid('duplicate_pii_placeholder');
    allowedPlaceholders.add(entry.placeholder);
  }

  // Leere oder ausdrücklich unvollständige Responses werden eindeutig markiert.
  const messages = Array.isArray(input.output) ? input.output : [];
  if (messages.length === 0 || messages.some((message) => message?.status === 'incomplete')) {
    return invalid('ai_incomplete');
  }

  // Extrahiert genau einen Textblock aus dem Responses-API-Ausgabeformat.
  const textParts = [];
  for (const message of messages) {
    if (!Array.isArray(message.content)) continue;
    for (const content of message.content) {
      if (content && content.type === 'output_text' && content.text !== undefined) textParts.push(content.text);
    }
  }
  if (textParts.length !== 1) return invalid('missing_or_multiple_output_text');
  const raw = textParts[0];
  const result = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!result || typeof result !== 'object' || Array.isArray(result)) return invalid('output_not_object');

  // Das strikte Ergebnisobjekt darf weder Felder verlieren noch zusätzliche Felder enthalten.
  const expectedKeys = ['classification', 'clarification_question', 'suggested_service', 'summary'].sort();
  const actualKeys = Object.keys(result).sort();
  if (actualKeys.length !== expectedKeys.length || actualKeys.some((key, index) => key !== expectedKeys[index])) return invalid('unexpected_output_keys');
  if (!allowedClassifications.has(result.classification)) return invalid('invalid_classification');
  if (result.suggested_service !== null && !allowedServices.has(result.suggested_service)) return invalid('invalid_suggested_service');
  if (typeof result.summary !== 'string' || !result.summary.trim() || result.summary.length > 600) return invalid('invalid_summary');
  if (result.clarification_question !== null && (typeof result.clarification_question !== 'string' || !result.clarification_question.trim() || result.clarification_question.length > 800)) return invalid('invalid_clarification_question');

  // Prüft Platzhalterintegrität und verbietet neu erzeugte Kontaktwerte oder Markdown.
  const generatedText = [result.summary, result.clarification_question || ''].join(' ');
  const emittedPlaceholders = generatedText.match(/\[\[PII_[A-Z]+_\d+\]\]/g) || [];
  if (emittedPlaceholders.some((placeholder) => !allowedPlaceholders.has(placeholder))) return invalid('unknown_pii_placeholder');
  let textWithoutAllowedPlaceholders = generatedText;
  for (const placeholder of allowedPlaceholders) textWithoutAllowedPlaceholders = textWithoutAllowedPlaceholders.split(placeholder).join('');
  if (/\[\[\s*PII_|PII_[A-Z]+_\d+\]?\]?/i.test(textWithoutAllowedPlaceholders)) return invalid('malformed_pii_placeholder');
  const forbidden = /(?:https?:\/\/|www\.|\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b|(?:^|\s)@[a-z0-9_][a-z0-9_.-]{1,}|(?:^|\s)\+?\d[\d\s().\/-]{6,}\d(?=\s|[.,;:!?]|$)|\[[^\]]+\]\([^)]+\)|\x60|^\s*#{1,6}\s|[*_]{2})/im.test(textWithoutAllowedPlaceholders);
  if (forbidden) return invalid('forbidden_generated_content');
  // Gleicht die KI-Entscheidung mit den festen lokalen Serviceregeln ab.
  if (result.classification === 'clear' && (result.suggested_service !== base.selected_service || result.clarification_question !== null)) return invalid('invalid_clear_result');
  if (result.classification !== 'clear' && typeof result.clarification_question !== 'string') return invalid('missing_clarification_question');
  if (result.classification === 'service_conflict' && (result.suggested_service === null || result.suggested_service === base.selected_service)) return invalid('invalid_conflict_result');
  if (base.rule_classification !== 'clear' && result.classification !== base.rule_classification) return invalid('ai_conflicts_with_local_rule');
  if (
    base.rule_classification === 'service_conflict' &&
    base.rule_message_service !== null &&
    result.suggested_service !== base.rule_message_service
  ) return invalid('ai_conflicts_with_local_service_scope');

  // Erst nach allen Prüfungen werden die vier erlaubten KI-Felder lokal freigegeben.
  return [{ json: {
    ...base,
    validation_status: 'valid',
    validation_error: null,
    classification: result.classification,
    suggested_service: result.suggested_service,
    summary: result.summary.trim(),
    clarification_question: result.clarification_question === null ? null : result.clarification_question.trim(),
  } }];
} catch (error) {
  // Abgeschnittenes oder anderweitig ungültiges JSON wird niemals teilweise übernommen.
  return invalid('unparseable_ai_output');
}

// Setzt erst nach vollständiger KI-Prüfung erlaubte Namensplatzhalter lokal wieder ein.
const item = $input.first().json;
if (item.validation_status !== 'valid') {
  return [{ json: { ...item, rehydration_status: 'not_applicable' } }];
}

// Die Platzhalterzuordnung und die kanonischen Namen stammen aus lokalen früheren Nodes.
// `.first()` ist korrekt, weil jeder Workflow-Lauf genau eine Anfrage verarbeitet.
const privacySource = $('Datenschutz und Serviceregeln prüfen').first().json;
const inquirySource = $('Anfrage für Auswertung laden').first().json;
const piiMap = Array.isArray(privacySource.pii_map) ? privacySource.pii_map : [];

// Erstellt die zulässigen Schreibweisen aus den ursprünglichen PostgreSQL-Feldern.
// Der Vergleich erfolgt kleinschreibungsunabhängig, eingesetzt wird die kanonische Formularschreibweise.
const firstName = typeof inquirySource.first_name === 'string' ? inquirySource.first_name.trim() : '';
const lastName = typeof inquirySource.last_name === 'string' ? inquirySource.last_name.trim() : '';
const fullName = [firstName, lastName].filter(Boolean).join(' ');
const canonicalNames = new Map();
for (const value of [fullName, firstName, lastName]) {
  if (value) canonicalNames.set(value.toLocaleLowerCase('de-DE'), value);
}

// Ein abgelehnter Fall enthält keinen teilweise wiederhergestellten Text.
const reject = (validation_error) => [{ json: {
  ...item,
  validation_status: 'invalid',
  validation_error,
  classification: null,
  suggested_service: null,
  summary: null,
  clarification_question: null,
  rehydration_status: 'rejected',
} }];

// Prüft die lokale Zuordnung erneut und verhindert doppelte oder beschädigte Platzhalter.
const placeholderPattern = /^\[\[PII_[A-Z]+_\d+\]\]$/;
const entries = new Map();
for (const entry of piiMap) {
  if (!entry || typeof entry.placeholder !== 'string' || !placeholderPattern.test(entry.placeholder)) {
    return reject('invalid_pii_map_for_reinsertion');
  }
  if (entries.has(entry.placeholder)) return reject('duplicate_pii_placeholder_for_reinsertion');
  entries.set(entry.placeholder, entry);
}

let replacementCount = 0;
const restoreText = (text) => {
  if (text === null) return { ok: true, value: null };
  if (typeof text !== 'string') return { ok: false, error: 'invalid_text_for_reinsertion' };

  let restored = text;
  const placeholders = restored.match(/\[\[PII_[A-Z]+_\d+\]\]/g) || [];
  for (const placeholder of placeholders) {
    const entry = entries.get(placeholder);

    // Nur bekannte NAME-Platzhalter dürfen Originalwerte zurückerhalten.
    // Kontaktwerte bleiben gesperrt, auch wenn OpenAI ihren Platzhalter wiederholt.
    if (
      !entry ||
      entry.reinsert_allowed !== true ||
      entry.type !== 'name' ||
      typeof entry.original_value !== 'string' ||
      !entry.original_value.trim()
    ) {
      return { ok: false, error: 'placeholder_not_allowed_for_reinsertion' };
    }

    // Verknüpft den erkannten Nachrichtentext mit Vorname, Nachname oder vollständigem Namen aus PostgreSQL.
    const canonicalValue = canonicalNames.get(entry.original_value.trim().toLocaleLowerCase('de-DE'));
    if (!canonicalValue) return { ok: false, error: 'placeholder_not_linked_to_known_name' };

    restored = restored.split(placeholder).join(canonicalValue);
    replacementCount += 1;
  }

  // Nach der Ersetzung darf kein vollständiger oder beschädigter PII-Platzhalter übrig bleiben.
  if (/\[\[\s*PII_|PII_[A-Z]+_\d+\]?\]?/i.test(restored)) {
    return { ok: false, error: 'unresolved_placeholder_after_reinsertion' };
  }
  return { ok: true, value: restored };
};

